create extension if not exists pgcrypto;
create extension if not exists btree_gist;
create schema if not exists barberium;

create table public.barbershops(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,status text not null default 'active' check(status in('active','inactive','suspended')),timezone text not null default 'America/Sao_Paulo',settings jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.units(id uuid primary key default gen_random_uuid(),barbershop_id uuid not null references public.barbershops(id) on delete cascade,name text not null,slug text not null,city text,state text,whatsapp text,maps_url text,is_active boolean not null default true,settings jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(barbershop_id,slug));
create table public.professionals(id uuid primary key default gen_random_uuid(),barbershop_id uuid not null references public.barbershops(id) on delete cascade,unit_id uuid not null references public.units(id) on delete cascade,name text not null,slug text not null,sort_order int not null default 0,image_path text,is_active boolean not null default true,settings jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(unit_id,slug));
create table public.services(id uuid primary key default gen_random_uuid(),barbershop_id uuid not null references public.barbershops(id) on delete cascade,unit_id uuid not null references public.units(id) on delete cascade,name text not null,slug text not null,price_cents int not null check(price_cents>=0),duration_min int not null check(duration_min>0),duration_label text,image_path text,sort_order int not null default 0,is_active boolean not null default true,settings jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(unit_id,slug));
create table public.service_addons(id uuid primary key default gen_random_uuid(),barbershop_id uuid not null references public.barbershops(id) on delete cascade,unit_id uuid not null references public.units(id) on delete cascade,base_service_id uuid not null references public.services(id) on delete cascade,addon_service_id uuid not null references public.services(id) on delete cascade,addon_price_cents int not null check(addon_price_cents>=0),addon_duration_min int not null check(addon_duration_min>=0),sort_order int not null default 0,is_active boolean not null default true,unique(base_service_id,addon_service_id),check(base_service_id<>addon_service_id));
create table public.professional_services(professional_id uuid not null references public.professionals(id) on delete cascade,service_id uuid not null references public.services(id) on delete cascade,is_active boolean not null default true,custom_price_cents int,custom_duration_min int,primary key(professional_id,service_id));
create table public.business_hours(id uuid primary key default gen_random_uuid(),unit_id uuid not null references public.units(id) on delete cascade,professional_id uuid references public.professionals(id) on delete cascade,weekday smallint not null check(weekday between 0 and 6),open_time time,close_time time,is_closed boolean not null default false,unique nulls not distinct(unit_id,professional_id,weekday),check(is_closed or(open_time is not null and close_time is not null and open_time<close_time)));
create table public.blocked_times(id uuid primary key default gen_random_uuid(),barbershop_id uuid not null references public.barbershops(id) on delete cascade,unit_id uuid not null references public.units(id) on delete cascade,professional_id uuid references public.professionals(id) on delete cascade,starts_at timestamptz not null,ends_at timestamptz not null,reason text,created_at timestamptz not null default now(),check(starts_at<ends_at));
create table public.customers(id uuid primary key default gen_random_uuid(),barbershop_id uuid not null references public.barbershops(id) on delete cascade,full_name text not null,phone_e164 text not null,birthday date,marketing_opt_in boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(barbershop_id,phone_e164));
create table public.customer_access_tokens(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.customers(id) on delete cascade,token_hash bytea not null unique,created_at timestamptz not null default now(),last_used_at timestamptz,revoked_at timestamptz);
create table public.appointments(id uuid primary key default gen_random_uuid(),barbershop_id uuid not null references public.barbershops(id) on delete cascade,unit_id uuid not null references public.units(id) on delete cascade,professional_id uuid not null references public.professionals(id),customer_id uuid not null references public.customers(id),service_id uuid not null references public.services(id),starts_at timestamptz not null,ends_at timestamptz not null,base_price_cents int not null,total_price_cents int not null,status text not null default 'confirmed' check(status in('confirmed','completed','cancelled','no_show')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),cancelled_at timestamptz,check(starts_at<ends_at));
alter table public.appointments add constraint appointments_no_overlap exclude using gist(professional_id with =,tstzrange(starts_at,ends_at,'[)') with &&) where(status='confirmed');
create table public.appointment_addons(appointment_id uuid not null references public.appointments(id) on delete cascade,service_id uuid not null references public.services(id),name_snapshot text not null,price_cents int not null,duration_min int not null,primary key(appointment_id,service_id));
create table public.barbershop_members(id uuid primary key default gen_random_uuid(),barbershop_id uuid not null references public.barbershops(id) on delete cascade,auth_user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in('owner','admin','staff')),professional_id uuid references public.professionals(id) on delete set null,is_active boolean not null default true,created_at timestamptz not null default now(),unique(barbershop_id,auth_user_id));

create index idx_appointments_professional_start on public.appointments(professional_id,starts_at);
create index idx_appointments_customer_start on public.appointments(customer_id,starts_at desc);
create index idx_blocked_times_professional_start on public.blocked_times(professional_id,starts_at);

create or replace function barberium.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create trigger trg_barbershops_updated_at before update on public.barbershops for each row execute function barberium.touch_updated_at();
create trigger trg_units_updated_at before update on public.units for each row execute function barberium.touch_updated_at();
create trigger trg_professionals_updated_at before update on public.professionals for each row execute function barberium.touch_updated_at();
create trigger trg_services_updated_at before update on public.services for each row execute function barberium.touch_updated_at();
create trigger trg_customers_updated_at before update on public.customers for each row execute function barberium.touch_updated_at();
create trigger trg_appointments_updated_at before update on public.appointments for each row execute function barberium.touch_updated_at();

alter table public.barbershops enable row level security; alter table public.units enable row level security; alter table public.professionals enable row level security; alter table public.services enable row level security; alter table public.service_addons enable row level security; alter table public.professional_services enable row level security; alter table public.business_hours enable row level security; alter table public.blocked_times enable row level security; alter table public.customers enable row level security; alter table public.customer_access_tokens enable row level security; alter table public.appointments enable row level security; alter table public.appointment_addons enable row level security; alter table public.barbershop_members enable row level security;
revoke all on public.barbershops,public.units,public.professionals,public.services,public.service_addons,public.professional_services,public.business_hours,public.blocked_times,public.customers,public.customer_access_tokens,public.appointments,public.appointment_addons,public.barbershop_members from anon,authenticated;

